 <?php $__env->startSection('content'); ?><div class="container my-3"><article class="paper-card"><div class="section-title">Payment Details</div><div class="paper-body"><p><b>Applicant:</b> <?php echo e($data['name']); ?><br><b>Amount:</b> ₹<?php echo e(number_format($data['amount'],2)); ?></p><button id="pay-button" class="btn btn-isar">Pay securely with Razorpay</button><p id="pay-message" class="mt-3 text-danger"></p></div></article></div><?php $__env->stopSection(); ?> <?php $__env->startPush('scripts'); ?><script src="https://checkout.razorpay.com/v1/checkout.js"></script><script>document.getElementById('pay-button').onclick=async()=>{let r=await fetch('<?php echo e(route('pay.order')); ?>',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':'<?php echo e(csrf_token()); ?>'},body:JSON.stringify({amount:<?php echo e($data['amount']); ?>,reference:'<?php echo e($data['reference'] ?? ''); ?>'})});if(!r.ok){document.getElementById('pay-message').textContent='Online payment is currently unavailable. Please contact the editorial office.';return}let o=await r.json();new Razorpay({key:o.key,amount:o.amount,currency:o.currency,name:'ISAR Publisher',order_id:o.id,handler:p=>{let f=document.createElement('form');f.method='POST';f.action='<?php echo e(route('pay')); ?>';f.innerHTML='<input name="_token" value="<?php echo e(csrf_token()); ?>">'+Object.entries(p).map(([k,v])=>'<input name="'+k+'" value="'+v+'">').join('');document.body.append(f);f.submit()}}).open()}</script><?php $__env->stopPush(); ?>

